"""Environment matrix applied after the dry render.

Impulse responses and noise are synthesized in this process. No proprietary
room or noise library is downloaded. Each spec records the source and the
licence of what it actually generates.
"""

from __future__ import annotations

from dataclasses import dataclass

from emotion_v2_dataset.errors import PipelineError

# Generated by tools/emotion-v2/dataset (audio.synthetic_impulse). No recording.
IR_SOURCE = (
    "in-process synthetic room impulse: unit direct path, sparse early taps, "
    "exponential RT60 decay. No recorded impulse response was downloaded."
)
IR_LICENCE = "CC0-1.0"
IR_DRY_SOURCE = "in-process unit impulse (no room). No recording was downloaded."

# Generated by tools/emotion-v2/dataset (audio.synthetic_noise). Not a field recording.
NOISE_SOURCE = (
    "in-process synthetic noise: filtered noise and detuned tones. "
    "Not a recording of a room, street, cafe, or person."
)
NOISE_LICENCE = "CC0-1.0"
NOISE_NONE_SOURCE = "none"
NOISE_NONE_LICENCE = "n/a"

PHONE_NOTE = (
    "narrowband simulation: in-process FFT brickwall 300-3400 Hz, then "
    "integer decimation to 8000 Hz. Not a carrier recording and not a "
    "downloaded telephony codec."
)
HEADSET_NOTE = (
    "headset simulation: in-process FFT brickwall 80-7500 Hz plus an "
    "ITU-T G.711 mu-law round trip (open specification). Not a Bluetooth "
    "SBC bitstream and not a vendor codec."
)


@dataclass(frozen=True)
class Environment:
    """One post-render condition.

    ``name`` is the manifest value. ``snr_db`` of None means no noise is added.
    ``nominal_snr_db`` is that same value; ``snr_levels`` is the set a caller
    can expand to. The default run uses ``nominal_snr_db`` only.
    """

    name: str
    rt60_s: float
    early_taps: int
    noise_kind: str
    nominal_snr_db: float | None
    snr_levels: tuple[float | None, ...]
    telephony_hz: int | None = None
    headset: bool = False
    ir_source: str = IR_SOURCE
    ir_licence: str = IR_LICENCE
    noise_source: str = NOISE_SOURCE
    noise_licence: str = NOISE_LICENCE
    process_note: str = ""


ENVIRONMENTS: tuple[Environment, ...] = (
    Environment(
        name="dry studio",
        rt60_s=0.0,
        early_taps=0,
        noise_kind="none",
        nominal_snr_db=None,
        snr_levels=(None,),
        ir_source=IR_DRY_SOURCE,
        noise_source=NOISE_NONE_SOURCE,
        noise_licence=NOISE_NONE_LICENCE,
        process_note="No reverberation and no added noise.",
    ),
    Environment(
        name="small room",
        rt60_s=0.28,
        early_taps=3,
        noise_kind="room",
        nominal_snr_db=25.0,
        snr_levels=(25.0, 15.0),
    ),
    Environment(
        name="living room",
        rt60_s=0.45,
        early_taps=4,
        noise_kind="room",
        nominal_snr_db=20.0,
        snr_levels=(20.0, 10.0),
    ),
    Environment(
        name="car",
        rt60_s=0.18,
        early_taps=2,
        noise_kind="rumble",
        nominal_snr_db=12.0,
        snr_levels=(12.0, 5.0),
    ),
    Environment(
        name="cafe/babble",
        rt60_s=0.55,
        early_taps=5,
        noise_kind="babble",
        nominal_snr_db=8.0,
        snr_levels=(15.0, 8.0, 5.0),
        process_note="Babble is detuned tones and noise, not recorded speech.",
    ),
    Environment(
        name="street",
        rt60_s=0.12,
        early_taps=2,
        noise_kind="street",
        nominal_snr_db=10.0,
        snr_levels=(15.0, 10.0, 5.0),
    ),
    Environment(
        name="phone/narrowband 8 kHz",
        rt60_s=0.08,
        early_taps=1,
        noise_kind="line",
        nominal_snr_db=15.0,
        snr_levels=(20.0, 15.0, 10.0),
        telephony_hz=8000,
        process_note=PHONE_NOTE,
    ),
    Environment(
        name="headset/bluetooth codec",
        rt60_s=0.05,
        early_taps=1,
        noise_kind="hiss",
        nominal_snr_db=18.0,
        snr_levels=(25.0, 18.0, 10.0),
        headset=True,
        process_note=HEADSET_NOTE,
    ),
)

_BY_NAME = {item.name: item for item in ENVIRONMENTS}
_ALIASES = {
    "dry_studio": "dry studio",
    "dry-studio": "dry studio",
    "small_room": "small room",
    "small-room": "small room",
    "living_room": "living room",
    "living-room": "living room",
    "cafe_babble": "cafe/babble",
    "cafe-babble": "cafe/babble",
    "phone_narrowband": "phone/narrowband 8 kHz",
    "phone-narrowband": "phone/narrowband 8 kHz",
    "phone": "phone/narrowband 8 kHz",
    "headset_bluetooth": "headset/bluetooth codec",
    "headset-bluetooth": "headset/bluetooth codec",
    "headset": "headset/bluetooth codec",
}


def environment_names() -> tuple[str, ...]:
    return tuple(item.name for item in ENVIRONMENTS)


def get_environment(name: str) -> Environment:
    key = name.strip()
    key = _ALIASES.get(key, key)
    found = _BY_NAME.get(key)
    if found is None:
        known = ", ".join(environment_names())
        raise PipelineError(f"unknown environment {name!r}; expected one of: {known}")
    return found


def resolve_environments(names: tuple[str, ...] | None) -> tuple[Environment, ...]:
    if names is None:
        return ENVIRONMENTS
    return tuple(get_environment(name) for name in names)


def snr_for(environment: Environment, override: tuple[float | None, ...] | None) -> tuple[float | None, ...]:
    """SNR values to render for one environment.

    An override replaces the nominal level on noisy environments. Dry studio
    stays dry: a noise level would stop it being the dry anchor.
    """
    if environment.nominal_snr_db is None:
        return (None,)
    if override is None:
        return (environment.nominal_snr_db,)
    if any(level is None for level in override):
        raise PipelineError("SNR override values must be numbers in dB")
    return override
